function initDrawTools(map2) {
  const draw2 = new ci({
    modes: [
      "point",
      "linestring",
      "polygon",
      "rectangle",
      "circle",
      "freehand",
      "angled-rectangle",
      "sensor",
      "sector",
      "select",
      "delete-selection",
      "delete",
      "download"
    ],
    open: true
  });
  map2.addControl(draw2, "top-left");
  const container = map2.getContainer().querySelector(".maplibregl-terradraw-add-control").parentElement;
  container.id = "terradraw-tools";
  container.setAttribute("role", "toolbar");
  container.setAttribute("aria-label", "Ferramentas TerraDraw");
  container.style.display = "none";
  return draw2;
}
function setDrawToolsOpen(map2, draw2, isOpen) {
  const container = map2.getContainer().querySelector("#terradraw-tools");
  container.style.display = isOpen ? "" : "none";
  if (isOpen) {
    draw2.activate();
  } else {
    draw2.deactivate();
  }
}

