var TERRAIN_SOURCE = {
  type: "raster-dem",
  tiles: ["https://tiles.mapterhorn.com/{z}/{x}/{y}.webp"],
  encoding: "terrarium",
  tileSize: 512,
  // MAX zoom level of detail from the heightmap 
  maxzoom: 13
};

// js/ui/terrainToggle.js
function initTerrain(map2) {
  map2.on("style.load", () => {
    if (!map2.getSource("terrain")) {
      map2.addSource("terrain", TERRAIN_SOURCE);
    }
    map2.setTerrain({
      source: "terrain",
      exaggeration: 1.5
    });
  });
}

